//! spotlight_window
//! Topmost floating Spotlight search bar window with global hotkey support.
//!
//! Windows: DirectComposition layered window centered at 25% screen top,
//! global hotkey (Alt+Space), automatic kill-focus dismissal, and keyboard navigation.
//! Non-Windows: High-fidelity mock window for unit testing and development.

use std::collections::VecDeque;

/// Events generated by user interaction with Spotlight.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SpotlightEvent {
    Opened,
    Closed,
    QueryChanged(String),
    Execute,
    Navigate(i32), // -1 for Up, +1 for Down
    Escaped,
}

/// Configuration for Spotlight floating window.
#[derive(Debug, Clone, PartialEq)]
pub struct SpotlightWindowConfig {
    pub width: u32,
    pub resting_height: u32,
    pub max_height: u32,
    pub title: String,
    pub class_name: String,
}

impl Default for SpotlightWindowConfig {
    fn default() -> Self {
        Self {
            width: 640,
            resting_height: 56,
            max_height: 420,
            title: "Spotlight".to_string(),
            class_name: "MacWinLauncherSpotlightClass".to_string(),
        }
    }
}

// ---------------------------------------------------------------------------
// Windows Implementation (DirectComposition Floating Search Bar)
// ---------------------------------------------------------------------------

#[cfg(windows)]
mod win32 {
    use super::*;
    use std::sync::{Arc, Mutex};
    use windows::core::PCWSTR;
    use windows::Win32::Foundation::{HWND, LPARAM, LRESULT, WPARAM};
    use windows::Win32::System::LibraryLoader::GetModuleHandleW;
    use windows::Win32::UI::Input::KeyboardAndMouse::{
        RegisterHotKey, SetFocus, UnregisterHotKey, MOD_ALT, MOD_CONTROL, MOD_NOREPEAT, VK_BACK,
        VK_DOWN, VK_ESCAPE, VK_RETURN, VK_SPACE, VK_UP,
    };
    use windows::Win32::UI::WindowsAndMessaging::{
        CreateWindowExW, DefWindowProcW, DestroyWindow, DispatchMessageW, GetSystemMetrics,
        GetWindowLongPtrW, PeekMessageW, RegisterClassExW, SetForegroundWindow, SetWindowLongPtrW,
        SetWindowPos, ShowWindow, TranslateMessage, CS_HREDRAW, CS_VREDRAW, GWLP_USERDATA,
        HWND_TOPMOST, MSG, PM_REMOVE, SM_CXSCREEN, SM_CYSCREEN, SWP_NOACTIVATE, SWP_NOMOVE,
        SWP_NOZORDER, SW_HIDE, SW_SHOW, WNDCLASSEXW, WS_EX_NOREDIRECTIONBITMAP, WS_EX_TOOLWINDOW,
        WS_EX_TOPMOST, WS_POPUP,
    };

    const HOTKEY_ID_PRIMARY: i32 = 1001;
    const HOTKEY_ID_FALLBACK: i32 = 1002;

    struct WindowSharedState {
        events: Mutex<VecDeque<SpotlightEvent>>,
        query: Mutex<String>,
        selected_index: Mutex<usize>,
        is_visible: Mutex<bool>,
    }

    pub struct Win32SpotlightWindow {
        hwnd: HWND,
        config: SpotlightWindowConfig,
        shared_state: Arc<WindowSharedState>,
        current_height: u32,
        primary_hotkey_registered: bool,
        fallback_hotkey_registered: bool,
    }

    unsafe extern "system" fn spotlight_wndproc(
        hwnd: HWND,
        msg: u32,
        wparam: WPARAM,
        lparam: LPARAM,
    ) -> LRESULT {
        use windows::Win32::UI::WindowsAndMessaging::{
            WM_CHAR, WM_HOTKEY, WM_KEYDOWN, WM_KILLFOCUS,
        };

        let ptr = GetWindowLongPtrW(hwnd, GWLP_USERDATA) as *mut WindowSharedState;
        if ptr.is_null() {
            return DefWindowProcW(hwnd, msg, wparam, lparam);
        }

        let state = &*ptr;

        match msg {
            WM_HOTKEY => {
                let should_hide = {
                    let mut vis = state.is_visible.lock().unwrap();
                    let was_vis = *vis;
                    *vis = !was_vis;
                    was_vis
                };
                if should_hide {
                    let _ = ShowWindow(hwnd, SW_HIDE);
                    state.query.lock().unwrap().clear();
                    state.events.lock().unwrap().push_back(SpotlightEvent::Closed);
                } else {
                    let _ = ShowWindow(hwnd, SW_SHOW);
                    let _ = SetForegroundWindow(hwnd);
                    let _ = SetFocus(hwnd);
                    state.events.lock().unwrap().push_back(SpotlightEvent::Opened);
                }
                LRESULT(0)
            }
            WM_KILLFOCUS => {
                let was_vis = {
                    let mut vis = state.is_visible.lock().unwrap();
                    let was = *vis;
                    *vis = false;
                    was
                };
                if was_vis {
                    let _ = ShowWindow(hwnd, SW_HIDE);
                    state.query.lock().unwrap().clear();
                    state.events.lock().unwrap().push_back(SpotlightEvent::Closed);
                }
                LRESULT(0)
            }
            WM_KEYDOWN => {
                let key = wparam.0 as u16;
                if key == VK_ESCAPE.0 {
                    let was_vis = {
                        let mut vis = state.is_visible.lock().unwrap();
                        let was = *vis;
                        *vis = false;
                        was
                    };
                    if was_vis {
                        let _ = ShowWindow(hwnd, SW_HIDE);
                        state.query.lock().unwrap().clear();
                    }
                    let mut events = state.events.lock().unwrap();
                    events.push_back(SpotlightEvent::Escaped);
                    events.push_back(SpotlightEvent::Closed);
                    return LRESULT(0);
                } else if key == VK_RETURN.0 {
                    state.events.lock().unwrap().push_back(SpotlightEvent::Execute);
                    return LRESULT(0);
                } else if key == VK_UP.0 {
                    state.events.lock().unwrap().push_back(SpotlightEvent::Navigate(-1));
                    return LRESULT(0);
                } else if key == VK_DOWN.0 {
                    state.events.lock().unwrap().push_back(SpotlightEvent::Navigate(1));
                    return LRESULT(0);
                } else if key == VK_BACK.0 {
                    let mut q = state.query.lock().unwrap();
                    if !q.is_empty() {
                        q.pop();
                        let current_q = q.clone();
                        drop(q);
                        state
                            .events
                            .lock()
                            .unwrap()
                            .push_back(SpotlightEvent::QueryChanged(current_q));
                    }
                    return LRESULT(0);
                }
                DefWindowProcW(hwnd, msg, wparam, lparam)
            }
            WM_CHAR => {
                let ch_code = wparam.0 as u32;
                // Exclude control characters (newline, tab, backspace, escape)
                if ch_code >= 32 && ch_code != 127 {
                    if let Some(ch) = char::from_u32(ch_code) {
                        let mut q = state.query.lock().unwrap();
                        q.push(ch);
                        let current_q = q.clone();
                        drop(q);
                        state
                            .events
                            .lock()
                            .unwrap()
                            .push_back(SpotlightEvent::QueryChanged(current_q));
                    }
                }
                LRESULT(0)
            }
            _ => DefWindowProcW(hwnd, msg, wparam, lparam),
        }
    }

    impl Win32SpotlightWindow {
        pub fn new(config: SpotlightWindowConfig) -> Result<Self, String> {
            unsafe {
                let hinstance = GetModuleHandleW(PCWSTR::null())
                    .map_err(|e| format!("Failed to get module handle: {e}"))?;

                let class_name_utf16: Vec<u16> = config
                    .class_name
                    .encode_utf16()
                    .chain(std::iter::once(0))
                    .collect();

                let wnd_class = WNDCLASSEXW {
                    cbSize: std::mem::size_of::<WNDCLASSEXW>() as u32,
                    style: CS_HREDRAW | CS_VREDRAW,
                    lpfnWndProc: Some(spotlight_wndproc),
                    cbClsExtra: 0,
                    cbWndExtra: 0,
                    hInstance: hinstance.into(),
                    hIcon: Default::default(),
                    hCursor: Default::default(),
                    hbrBackground: Default::default(),
                    lpszMenuName: PCWSTR::null(),
                    lpszClassName: PCWSTR(class_name_utf16.as_ptr()),
                    hIconSm: Default::default(),
                };

                let _ = RegisterClassExW(&wnd_class);

                let screen_width = GetSystemMetrics(SM_CXSCREEN);
                let screen_height = GetSystemMetrics(SM_CYSCREEN);

                let x = (screen_width - config.width as i32) / 2;
                // Position at 22% from top of screen, matching macOS Spotlight
                let y = (screen_height as f32 * 0.22) as i32;

                let title_utf16: Vec<u16> =
                    config.title.encode_utf16().chain(std::iter::once(0)).collect();

                let hwnd = CreateWindowExW(
                    WS_EX_NOREDIRECTIONBITMAP | WS_EX_TOPMOST | WS_EX_TOOLWINDOW,
                    PCWSTR(class_name_utf16.as_ptr()),
                    PCWSTR(title_utf16.as_ptr()),
                    WS_POPUP,
                    x,
                    y,
                    config.width as i32,
                    config.resting_height as i32,
                    None,
                    None,
                    hinstance,
                    None,
                )
                .map_err(|e| format!("Failed to create Spotlight window: {e}"))?;

                let shared_state = Arc::new(WindowSharedState {
                    events: Mutex::new(VecDeque::new()),
                    query: Mutex::new(String::new()),
                    selected_index: Mutex::new(0),
                    is_visible: Mutex::new(false),
                });

                SetWindowLongPtrW(
                    hwnd,
                    GWLP_USERDATA,
                    Arc::as_ptr(&shared_state) as *const _ as isize,
                );

                // Register global hotkeys:
                // Primary: Alt + Space (macOS Command+Space equivalent)
                let primary_reg = RegisterHotKey(
                    hwnd,
                    HOTKEY_ID_PRIMARY,
                    MOD_ALT | MOD_NOREPEAT,
                    VK_SPACE.0 as u32,
                )
                .is_ok();

                // Fallback: Ctrl + Space (if Alt+Space was reserved)
                let fallback_reg = if !primary_reg {
                    RegisterHotKey(
                        hwnd,
                        HOTKEY_ID_FALLBACK,
                        MOD_CONTROL | MOD_NOREPEAT,
                        VK_SPACE.0 as u32,
                    )
                    .is_ok()
                } else {
                    false
                };

                Ok(Self {
                    hwnd,
                    current_height: config.resting_height,
                    config,
                    shared_state,
                    primary_hotkey_registered: primary_reg,
                    fallback_hotkey_registered: fallback_reg,
                })
            }
        }

        pub fn show(&mut self) {
            unsafe {
                *self.shared_state.is_visible.lock().unwrap() = true;
                let _ = ShowWindow(self.hwnd, SW_SHOW);
                let _ = SetForegroundWindow(self.hwnd);
                let _ = SetFocus(self.hwnd);
                self.shared_state
                    .events
                    .lock()
                    .unwrap()
                    .push_back(SpotlightEvent::Opened);
            }
        }

        pub fn hide(&mut self) {
            unsafe {
                *self.shared_state.is_visible.lock().unwrap() = false;
                let _ = ShowWindow(self.hwnd, SW_HIDE);
                self.reset_query();
                self.reset_height();
                self.shared_state
                    .events
                    .lock()
                    .unwrap()
                    .push_back(SpotlightEvent::Closed);
            }
        }

        pub fn toggle(&mut self) {
            if self.is_visible() {
                self.hide();
            } else {
                self.show();
            }
        }

        pub fn is_visible(&self) -> bool {
            *self.shared_state.is_visible.lock().unwrap()
        }

        pub fn poll_events(&mut self) -> Vec<SpotlightEvent> {
            unsafe {
                let mut msg = MSG::default();
                while PeekMessageW(&mut msg, self.hwnd, 0, 0, PM_REMOVE).as_bool() {
                    let _ = TranslateMessage(&msg);
                    DispatchMessageW(&msg);
                }
            }
            let mut queue = self.shared_state.events.lock().unwrap();
            queue.drain(..).collect()
        }

        pub fn width(&self) -> u32 {
            self.config.width
        }

        pub fn height(&self) -> u32 {
            self.current_height
        }

        pub fn set_height(&mut self, height: u32) {
            let clamped = height.clamp(self.config.resting_height, self.config.max_height);
            if self.current_height != clamped {
                self.current_height = clamped;
                unsafe {
                    let _ = SetWindowPos(
                        self.hwnd,
                        HWND_TOPMOST,
                        0,
                        0,
                        self.config.width as i32,
                        clamped as i32,
                        SWP_NOMOVE | SWP_NOZORDER | SWP_NOACTIVATE,
                    );
                }
            }
        }

        pub fn reset_height(&mut self) {
            self.set_height(self.config.resting_height);
        }

        pub fn reset_query(&mut self) {
            self.shared_state.query.lock().unwrap().clear();
            *self.shared_state.selected_index.lock().unwrap() = 0;
        }

        pub fn query(&self) -> String {
            self.shared_state.query.lock().unwrap().clone()
        }

        pub fn selected_index(&self) -> usize {
            *self.shared_state.selected_index.lock().unwrap()
        }

        pub fn set_selected_index(&mut self, idx: usize) {
            *self.shared_state.selected_index.lock().unwrap() = idx;
        }

        pub fn push_event(&mut self, event: SpotlightEvent) {
            self.shared_state.events.lock().unwrap().push_back(event);
        }

        pub fn hwnd(&self) -> HWND {
            self.hwnd
        }
    }

    impl Drop for Win32SpotlightWindow {
        fn drop(&mut self) {
            unsafe {
                if self.primary_hotkey_registered {
                    let _ = UnregisterHotKey(self.hwnd, HOTKEY_ID_PRIMARY);
                }
                if self.fallback_hotkey_registered {
                    let _ = UnregisterHotKey(self.hwnd, HOTKEY_ID_FALLBACK);
                }
                SetWindowLongPtrW(self.hwnd, GWLP_USERDATA, 0);
                let _ = DestroyWindow(self.hwnd);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Cross-Platform Mock Implementation
// ---------------------------------------------------------------------------

#[derive(Debug)]
pub struct MockSpotlightWindow {
    config: SpotlightWindowConfig,
    is_visible: bool,
    current_height: u32,
    query: String,
    selected_index: usize,
    events: VecDeque<SpotlightEvent>,
}

impl MockSpotlightWindow {
    pub fn new(config: SpotlightWindowConfig) -> Self {
        Self {
            current_height: config.resting_height,
            config,
            is_visible: false,
            query: String::new(),
            selected_index: 0,
            events: VecDeque::new(),
        }
    }

    pub fn show(&mut self) {
        if !self.is_visible {
            self.is_visible = true;
            self.events.push_back(SpotlightEvent::Opened);
        }
    }

    pub fn hide(&mut self) {
        if self.is_visible {
            self.is_visible = false;
            self.reset_query();
            self.reset_height();
            self.events.push_back(SpotlightEvent::Closed);
        }
    }

    pub fn toggle(&mut self) {
        if self.is_visible {
            self.hide();
        } else {
            self.show();
        }
    }

    pub fn is_visible(&self) -> bool {
        self.is_visible
    }

    pub fn poll_events(&mut self) -> Vec<SpotlightEvent> {
        self.events.drain(..).collect()
    }

    pub fn push_event(&mut self, event: SpotlightEvent) {
        self.events.push_back(event);
    }

    pub fn width(&self) -> u32 {
        self.config.width
    }

    pub fn height(&self) -> u32 {
        self.current_height
    }

    pub fn set_height(&mut self, height: u32) {
        self.current_height = height.clamp(self.config.resting_height, self.config.max_height);
    }

    pub fn reset_height(&mut self) {
        self.current_height = self.config.resting_height;
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn set_query(&mut self, q: impl Into<String>) {
        self.query = q.into();
        self.events
            .push_back(SpotlightEvent::QueryChanged(self.query.clone()));
    }

    pub fn reset_query(&mut self) {
        self.query.clear();
        self.selected_index = 0;
    }

    pub fn selected_index(&self) -> usize {
        self.selected_index
    }

    pub fn set_selected_index(&mut self, idx: usize) {
        self.selected_index = idx;
    }
}

// ---------------------------------------------------------------------------
// Unified SpotlightWindow Wrapper
// ---------------------------------------------------------------------------

enum SpotlightWindowInner {
    #[cfg(windows)]
    Real(win32::Win32SpotlightWindow),
    Mock(MockSpotlightWindow),
}

/// Unified Spotlight window presenting identical interfaces across platforms.
pub struct SpotlightWindow {
    inner: SpotlightWindowInner,
}

impl SpotlightWindow {
    /// Creates a mock Spotlight window for testing and development.
    pub fn new_mock() -> Self {
        Self {
            inner: SpotlightWindowInner::Mock(MockSpotlightWindow::new(SpotlightWindowConfig::default())),
        }
    }

    /// Creates a new Spotlight window with default config.
    pub fn new() -> Result<Self, String> {
        #[cfg(windows)]
        {
            let win = win32::Win32SpotlightWindow::new(SpotlightWindowConfig::default())?;
            Ok(Self { inner: SpotlightWindowInner::Real(win) })
        }
        #[cfg(not(windows))]
        {
            Ok(Self {
                inner: SpotlightWindowInner::Mock(MockSpotlightWindow::new(SpotlightWindowConfig::default())),
            })
        }
    }

    pub fn show(&mut self) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.show(),
            SpotlightWindowInner::Mock(w) => w.show(),
        }
    }

    pub fn hide(&mut self) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.hide(),
            SpotlightWindowInner::Mock(w) => w.hide(),
        }
    }

    pub fn toggle(&mut self) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.toggle(),
            SpotlightWindowInner::Mock(w) => w.toggle(),
        }
    }

    pub fn is_visible(&self) -> bool {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.is_visible(),
            SpotlightWindowInner::Mock(w) => w.is_visible(),
        }
    }

    pub fn poll_events(&mut self) -> Vec<SpotlightEvent> {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.poll_events(),
            SpotlightWindowInner::Mock(w) => w.poll_events(),
        }
    }

    pub fn push_event(&mut self, event: SpotlightEvent) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.push_event(event),
            SpotlightWindowInner::Mock(w) => w.push_event(event),
        }
    }

    pub fn width(&self) -> u32 {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.width(),
            SpotlightWindowInner::Mock(w) => w.width(),
        }
    }

    pub fn height(&self) -> u32 {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.height(),
            SpotlightWindowInner::Mock(w) => w.height(),
        }
    }

    pub fn set_height(&mut self, height: u32) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.set_height(height),
            SpotlightWindowInner::Mock(w) => w.set_height(height),
        }
    }

    pub fn reset_height(&mut self) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.reset_height(),
            SpotlightWindowInner::Mock(w) => w.reset_height(),
        }
    }

    pub fn query(&self) -> String {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.query(),
            SpotlightWindowInner::Mock(w) => w.query().to_string(),
        }
    }

    pub fn selected_index(&self) -> usize {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.selected_index(),
            SpotlightWindowInner::Mock(w) => w.selected_index(),
        }
    }

    pub fn set_selected_index(&mut self, idx: usize) {
        match &mut self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.set_selected_index(idx),
            SpotlightWindowInner::Mock(w) => w.set_selected_index(idx),
        }
    }

    pub fn hwnd(&self) -> isize {
        match &self.inner {
            #[cfg(windows)]
            SpotlightWindowInner::Real(w) => w.hwnd().0 as isize,
            SpotlightWindowInner::Mock(_) => 0,
        }
    }
}
